update public.modules as m set
  description_en = v.description_en,
  description_pcm = v.description_pcm,
  estimated_duration = v.estimated_duration,
  image_url = v.image_url,
  learning_objectives_en = v.learning_objectives_en,
  learning_objectives_pcm = v.learning_objectives_pcm,
  key_takeaways_en = v.key_takeaways_en,
  key_takeaways_pcm = v.key_takeaways_pcm,
  scenario_en = v.scenario_en,
  scenario_pcm = v.scenario_pcm,
  content_en = v.content_en,
  content_pcm = v.content_pcm
from (values
  (1, 'Learn how to identify and protect yourself from fraudulent messages designed to steal your sensitive information.', 'Learn how to catch fake messages wey scammers dey use thief your secret details.', 7, '/assets/smeshield/scenarios/fake-sms.jpg', '["Understand what phishing is", "Recognize common signs of fake alerts", "Know the correct way to verify bank messages"]'::jsonb, '["Understand wetin phishing be", "Know how to spot fake alert", "Learn the correct way to confirm message from your bank"]'::jsonb, '["Your bank will never ask for your PIN via SMS.", "Always verify urgent messages by logging directly into your bank app.", "Do not click links in unsolicited messages."]'::jsonb, '["Bank no go ever ask for your PIN inside SMS.", "Always log inside your bank app to confirm any urgent message.", "No click any link inside message wey you no expect."]'::jsonb, '{
    "situation": "You receive an SMS claiming your bank account will be blocked in 24 hours unless you click a link to verify your BVN.", "warning_signs": ["Creates a false sense of urgency", "Contains a strange URL link", "Asks for sensitive BVN/PIN info"], "risky_action": "Clicking the link and entering your details because you are afraid of losing access.", "safe_action": "Ignoring the link, and opening your official banking app directly to check your account status.", "explanation": "Scammers use panic to make you act without thinking. Banks do not threaten account blocks via SMS links."
  }'::jsonb, '{
    "situation": "You see SMS wey talk say dem go block your account in 24 hours if you no click link to update your BVN.", "warning_signs": ["Dem dey rush you make you panic", "The link look very anyhow", "Dem dey ask for your BVN or PIN"], "risky_action": "To click the link and drop your details because you dey fear make dem no block your money.", "safe_action": "To ignore the message, con open your normal bank app by yourself to check if anything happen.", "explanation": "Scammers dey use fear catch people. Real bank no go ever use SMS link threaten you."
  }'::jsonb, E'Phishing is when a scammer sends an email, SMS, or WhatsApp message pretending to be your bank, a government agency, or a trusted company. Their goal is to trick you into revealing sensitive information like your ATM PIN, BVN, or passwords.\n\nNever click on links from unexpected messages. If you are unsure, contact your bank directly using the phone number on the back of your ATM card.', E'Phishing na when scammer send you email, SMS, or WhatsApp message dey pretend say dem be your bank, government, or one big company. Wetin dem want na to trick you make you give dem your ATM PIN, BVN, or password.\n\nNo ever click link from message wey you no expect. If you no sure, call your bank direct with the phone number wey dey the back of your ATM card.'),
  (2, 'Protect your business from fraudsters using edited receipts and fake bank alerts to steal goods.', 'Protect your business from scammers wey dey use fake receipt and fake alert thief market.', 5, '/assets/smeshield/modules/fake-payment-hero.jpg', '["Identify manipulated payment receipts", "Understand the danger of relying solely on SMS alerts", "Implement a secure payment verification process"]'::jsonb, '["Know how to spot receipt wey dem don edit", "Understand why to rely on SMS alert dangerous", "Learn better way to confirm payment for your shop"]'::jsonb, '["Never release goods based on a screenshot.", "SMS alerts can be faked; log into your banking app.", "If a customer is too impatient, it is a red flag."]'::jsonb, '["No give anybody goods because of screenshot.", "Dem fit fake SMS alert; always check your bank app.", "If customer dey rush you too much, na red flag."]'::jsonb, '{
    "situation": "A customer buys items worth ₦150,000, shows you a transfer receipt on their phone, and aggressively demands the goods because they are in a hurry.", "warning_signs": ["Customer refuses to wait", "Shows only a screenshot or SMS", "Becomes aggressive when you try to verify"], "risky_action": "Handing over the goods to avoid an argument, assuming the bank network is just slow.", "safe_action": "Politely but firmly stating that goods can only be released after the funds reflect in your available bank balance.", "explanation": "Flash funds and edited receipts look real. The only source of truth is your own banking application."
  }'::jsonb, '{
    "situation": "Customer buy market of ₦150,000, show you receipt for their phone, con dey make shakara say dem dey rush make you give dem the goods.", "warning_signs": ["Customer no want wait at all", "Na only screenshot or SMS dem show", "Dem dey vex when you want verify"], "risky_action": "To give dem the goods so that quarrel no go start, thinking say maybe na bank network dey delay.", "safe_action": "To tell dem respectfully say you no fit release market until you see the money inside your own bank app balance.", "explanation": "Fake receipt and flash fund dey look exactly like real one. The only true confirmation na your own bank app."
  }'::jsonb, E'Fraudsters often use fake bank transfer alerts or edited screenshots to pretend they have paid for goods. By the time you realize the money never entered your account, they have already left with your merchandise.\n\nAlways ensure your staff is trained on this verification process.', E'Scammers dey use fake bank transfer alert or screenshot wey dem don edit to pretend say dem don pay for your market. Before you go know say money no enter your account, dem don carry your goods run.\n\nMake sure say you train your boys and girls on top this matter.'),
  (3, 'Learn how ransomware locks your business files and what you must do to prevent total data loss.', 'Learn how ransomware dey block your business files and wetin you must do so you no go lose everything.', 8, null, '["Understand how ransomware infects computers", "Know the risks of paying ransoms", "Learn how to backup business data effectively"]'::jsonb, '["Understand how ransomware dey enter computer", "Know the danger if you pay the ransom", "Learn the best way to backup your business data"]'::jsonb, '["Do not open unsolicited email attachments.", "Paying a ransom never guarantees you get your files back.", "Frequent offsite backups are your only true defense."]'::jsonb, '["No open email attachment wey you no know.", "To pay ransom no mean say dem go open your files.", "To always backup your files for cloud na the only sure way."]'::jsonb, '{
    "situation": "You open an invoice attachment from an unknown supplier. Suddenly, your screen turns red, and all your business spreadsheets are locked with a demand for Bitcoin.", "warning_signs": ["Unexpected email attachment", "Unusual file extensions (.crypt)", "Ransom demand screen"], "risky_action": "Paying the hacker and hoping they send the decryption key.", "safe_action": "Disconnecting the computer from the internet immediately and restoring files from your backup.", "explanation": "Ransomware spreads quickly through networks. Disconnecting isolates it. Having backups means you can ignore the ransom."
  }'::jsonb, '{
    "situation": "You open invoice attachment from supplier wey you no know. Sharp-sharp, your screen turn red, all your market records don lock and dem dey demand Bitcoin.", "warning_signs": ["Email attachment wey you no expect", "Your files don change name (.crypt)", "Dem put message say make you pay ransom"], "risky_action": "To pay the hacker and pray say dem go open your files.", "safe_action": "To disconnect the computer from internet immediately and bring your data back from your backup.", "explanation": "Ransomware dey spread fast for network. If you disconnect am, you stop am. If you get backup, you no need pay anybody."
  }'::jsonb, E'Ransomware is a type of malicious software that locks you out of your own computer or encrypts your business files so you can\'t open them. The attackers then demand a ransom (usually in cryptocurrency) to give you back access.\n\nAlways backup your important business data to an external hard drive or secure cloud storage (like Google Drive). Never pay the ransom.', E'Ransomware na one bad software wey go lock your computer or block all your business files make you no fit open dem. The attackers go con tell you say make you pay ransom (mostly with Bitcoin) before dem go give you access back.\n\nMake sure say you always save your important business data for external hard drive or secure cloud storage (like Google Drive). No ever pay the ransom.'),
  (4, 'Secure your business WhatsApp and social media pages from hackers who want to scam your customers.', 'Secure your business WhatsApp and social media from hackers wey want use am scam your customers.', 6, null, '["Enable Two-Step Verification (2FA)", "Recognize social engineering tricks used to steal access codes", "Know how to recover a compromised account"]'::jsonb, '["Know how to set Two-Step Verification (2FA)", "Spot the trick hackers dey use steal WhatsApp code", "Know wetin to do if dem hack your account"]'::jsonb, '["Never share your 6-digit SMS verification code with anyone.", "Enable Two-Step verification with a PIN on WhatsApp and Instagram.", "If a friend asks for money urgently via chat, call them first."]'::jsonb, '["No ever give anybody your 6-digit SMS verification code.", "Put Two-Step verification PIN for your WhatsApp and Instagram.", "If your friend ask for money urgent inside chat, call dem first."]'::jsonb, '{
    "situation": "A known contact messages you saying they accidentally sent a 6-digit code to your phone and urgently needs you to send it back.", "warning_signs": ["Unsolicited SMS verification code", "Urgent request from a contact acting unusually"], "risky_action": "Sending the code to help them out.", "safe_action": "Ignoring the request, deleting the code, and calling the contact directly to tell them their account is hacked.", "explanation": "The code sent to your phone is actually YOUR WhatsApp login code. Sharing it gives the hacker full access to your business account."
  }'::jsonb, '{
    "situation": "Somebody wey you know message you say dem mistakenly send 6-digit code to your phone, say make you abeg send am back fast.", "warning_signs": ["You receive SMS verification code out of nowhere", "The person dey rush you make you send am"], "risky_action": "To send the code so that you go help the person.", "safe_action": "To ignore the request, delete the code, con call the person direct tell am say hacker don hijack their account.", "explanation": "That code wey enter your phone na YOUR own WhatsApp login code. If you send am, you don hand over your business account to hacker."
  }'::jsonb, E'Account takeover occurs when a hacker gains access to your business social media or WhatsApp account. Once inside, they will message your customers, post fake investment schemes, or ask your suppliers for money.\n\nYour strongest defense is Two-Step Verification (2FA), which requires a custom PIN alongside your normal login details.', E'Account takeover na when hacker gain access to your business social media or WhatsApp account. Once dem enter, dem go begin message your customers, post fake investment, or ask your suppliers for money.\n\nYour biggest defense na Two-Step Verification (2FA), wey go ask for your special PIN anytime you want log in.'),
  (5, 'Understand the silent threats posed by infected USB drives and how they bypass standard network security.', 'Understand the silent danger of infected flash drive and how e dey bypass normal security.', 5, null, '["Understand how malware spreads via physical devices", "Identify the risks of keyloggers", "Implement secure USB practices for staff"]'::jsonb, '["Understand how virus dey spread through flash drive", "Know the danger of keyloggers wey dey record passwords", "Learn better flash drive rules for your workers"]'::jsonb, '["Never plug a found USB drive into a business computer.", "Scan all external drives with updated antivirus before opening files.", "Keyloggers can secretly record your banking passwords."]'::jsonb, '["No ever plug flash drive wey you see for ground inside work computer.", "Always scan any flash drive with antivirus before you open am.", "Keyloggers fit secretly record your bank passwords."]'::jsonb, '{
    "situation": "You find a brand-new 64GB flash drive on the floor of your shop and plug it into your sales computer to see who owns it.", "warning_signs": ["Abandoned USB drive", "No clear owner"], "risky_action": "Plugging it in and clicking on the files to find a name.", "safe_action": "Handing it to IT or throwing it away. Never plug untrusted hardware into your business systems.", "explanation": "Hackers frequently drop infected drives in public places. The moment you plug it in, a keylogger can install silently to steal your passwords."
  }'::jsonb, '{
    "situation": "You see brand-new 64GB flash drive for ground inside your shop, you con plug am for your sales computer to check who get am.", "warning_signs": ["Flash drive wey nobody get", "You no know where e come from"], "risky_action": "To plug am and start to click the files to find the owner name.", "safe_action": "To give IT or just throw am away. No ever plug hardware wey you no trust inside your business computer.", "explanation": "Hackers dey drop infected flash drive for public place. Immediately you plug am, virus (keylogger) fit install codedly to thief your passwords."
  }'::jsonb, E'Not all cyber threats come through the internet. Malware can be physically introduced into your systems via infected USB flash drives. Keyloggers, a specific type of malware, record every keystroke you make, allowing criminals to capture your passwords and banking details.\n\nKeep physical access to your business computers restricted and disable auto-run for USB drives.', E'No be all cyber attack dey come through internet. Virus fit enter your system physical through infected USB flash drive. Keyloggers, na one type of virus wey dey record everything you type for keyboard, so criminals go fit capture your password and bank details.\n\nMake sure say you restrict who dey access your business computers physical, and disable auto-run for flash drives.'),
  (6, 'Learn how fraudsters hijack your phone number to intercept your OTPs and wipe your bank accounts.', 'Learn how scammers dey hijack your phone number to steal your OTP and clear your bank account.', 7, null, '["Recognize the signs of an ongoing SIM Swap", "Understand how scammers intercept bank OTPs", "Know the immediate steps to take if your network drops unexpectedly"]'::jsonb, '["Know the signs say dem dey do SIM Swap on your line", "Understand how scammers dey intercept bank OTP", "Know wetin to do sharp-sharp if your network just disappear"]'::jsonb, '["A sudden, persistent loss of cellular signal is a major red flag.", "Scammers use SIM Swaps to bypass SMS-based Two-Factor Authentication.", "Link a secure email to your bank accounts, not just a phone number."]'::jsonb, '["If your network just disappear totally, na big red flag.", "Scammers dey use SIM Swap to bypass SMS verification.", "Link secure email to your bank account, no be only phone number."]'::jsonb, '{
    "situation": "Your phone suddenly says ''No Service'' in an area where you normally have strong signal, and it doesn''t come back after a restart.", "warning_signs": ["Unexpected loss of cellular service", "Other phones on the same network have signal"], "risky_action": "Assuming it is just a network glitch and waiting until tomorrow to check.", "safe_action": "Immediately using another phone to call your bank to block your accounts, then contacting your telecom provider.", "explanation": "When your phone says ''No Service'' unexpectedly, a scammer may have ported your number to their own SIM card to receive your banking OTPs."
  }'::jsonb, '{
    "situation": "Your phone just write ''No Service'' for place wey network dey always full, and e no come back even after you restart am.", "warning_signs": ["Network just disappear out of nowhere", "Other people using same network get signal"], "risky_action": "To just think say na normal network issue con wait till tomorrow.", "safe_action": "To immediately use another person phone call your bank make dem block your account, then call your network provider.", "explanation": "If your phone just write ''No Service'', e fit mean say scammer don transfer your number to their own SIM card so dem go fit receive your bank OTP."
  }'::jsonb, E'SIM Swap fraud occurs when a scammer convinces your mobile network provider to transfer your phone number to a new SIM card in their possession. Once they have your number, they receive all your SMS alerts, including One-Time Passwords (OTPs) for your bank.\n\nProtect your personal information online. Scammers use your birthdate, mother\'s maiden name, and BVN to convince telecom agents that they are you.', E'SIM Swap fraud na when scammer convince your network provider make dem transfer your phone number to new SIM card wey dey their hand. Once dem get your number, dem go dey receive all your SMS, including One-Time Password (OTP) for your bank.\n\nProtect your personal information online. Scammers dey use your date of birth, your mother name, and BVN take convince network agents say na you.'),
  (7, 'Prevent skimming and unauthorized transactions when operating a POS terminal for your business.', 'Stop scammers from stealing money from your POS machine when you dey do business.', 5, '/assets/smeshield/scenarios/pos-terminal.jpg', '["Understand how POS skimming works", "Identify suspicious customer behavior at checkout", "Enforce safe PIN handling rules"]'::jsonb, '["Understand how scammers dey use POS steal details", "Spot suspicious customer behavior when dem want pay", "Enforce safe PIN rules for your shop"]'::jsonb, '["Never ask a customer for their PIN.", "Do not let customers handle the POS terminal unsupervised.", "Check your terminal daily for attached skimming devices."]'::jsonb, '["No ever ask customer for their PIN.", "No allow customer hold your POS machine without monitoring.", "Check your POS everyday make sure say dem no attach anything."]'::jsonb, '{
    "situation": "A customer is struggling to enter their PIN on your POS machine and asks you to type it for them.", "warning_signs": ["Customer sharing their PIN openly", "Distractions during payment"], "risky_action": "Taking the card and typing the PIN for them to speed up the queue.", "safe_action": "Politely declining, asking them to type it secretly, or offering to cancel the transaction if they cannot remember it.", "explanation": "Handling a customer''s PIN makes you liable if fraud occurs on their account later."
  }'::jsonb, '{
    "situation": "Customer dey struggle to enter their PIN for your POS machine, dem con ask make you help dem type am.", "warning_signs": ["Customer dey call their PIN loud", "Dem dey distract you during payment"], "risky_action": "To collect the card and type the PIN for dem so that queue go move fast.", "safe_action": "To respectfully decline, tell dem make dem cover their hand type am, or cancel the transaction if dem don forget am.", "explanation": "If you hold customer PIN, you go enter wahala if scammers thief their money later."
  }'::jsonb, E'POS terminals are essential for retail, but they are also targets for fraudsters. Skimming devices can be attached to terminals to copy card details, and distracted agents can easily be tricked into accepting fake cards or approving reversed transactions.\n\nAlways maintain physical control of your terminal and verify the printed receipt says "Approved".', E'POS machine very important for business, but scammers too dey target am. Dem fit attach skimming device to the POS to copy card details, and if agent no focus, dem fit trick am to accept fake card or approve transaction wey no successful.\n\nAlways hold your POS machine well and make sure say the receipt print "Approved".'),
  (8, 'Learn why using "password123" across all your accounts is the easiest way for hackers to breach your business.', 'Learn why to use "password123" for all your account na the easiest way for hackers to enter your business.', 6, null, '["Understand the danger of credential reuse", "Create strong passphrases instead of complex passwords", "Implement a password manager"]'::jsonb, '["Understand the danger if you use same password everywhere", "Create strong passphrases instead of hard passwords", "Know how to use password manager"]'::jsonb, '["Use a different password for every important account.", "A long passphrase (e.g., ''BlueMonkeyEatsRice!'') is stronger than a short complex one.", "Use a password manager so you only have to remember one master password."]'::jsonb, '["Use different password for every important account.", "Long passphrase (like ''BlueMonkeyEatsRice!'') strong pass short hard password.", "Use password manager so you go only remember one master password."]'::jsonb, '{
    "situation": "You use the same password for your business email, your bank app, and a small online forum you joined years ago.", "warning_signs": ["Using the exact same password on multiple sites"], "risky_action": "Continuing to use it because it is easy to remember.", "safe_action": "Changing your critical passwords immediately to unique passphrases and saving them in a secure password manager.", "explanation": "If the small online forum gets hacked, criminals will try that same password on your bank and email accounts. This is called credential stuffing."
  }'::jsonb, '{
    "situation": "You dey use the same password for your business email, your bank app, and one small online forum wey you join since.", "warning_signs": ["Using the exact same password everywhere"], "risky_action": "To just continue dey use am because e easy to remember.", "safe_action": "To change your important passwords immediately to unique passphrases and save dem for password manager.", "explanation": "If hackers hack that small online forum, dem go carry that same password go try log into your bank and email. Dem call am credential stuffing."
  }'::jsonb, E'Hackers rarely "guess" passwords anymore. Instead, they buy massive lists of passwords leaked from hacked websites. If you use the same password for a fitness app and your business email, a breach at the fitness app gives hackers the key to your business.\n\nUse long passphrases and unique passwords for every service.', E'Hackers no dey "guess" password again. Wetin dem dey do na to buy big lists of passwords wey dem leak from hacked websites. If you use the same password for fitness app and your business email, if the fitness app leak, hackers don get the key to your business.\n\nUse long passphrases and unique passwords for every account.'),
  (9, 'Understand why clicking "Remind me later" on software updates leaves your business exposed to known vulnerabilities.', 'Understand why to click "Remind me later" for software update dey expose your business to hackers.', 5, null, '["Understand what a software patch is", "Recognize the risk of using outdated operating systems", "Enable automatic updates on business devices"]'::jsonb, '["Understand wetin software update be", "Know the danger to use old operating system", "Turn on automatic update for your business phones and computer"]'::jsonb, '["Updates fix security holes that hackers already know about.", "Turn on automatic updates on your phone and PC.", "If a device is too old to receive updates, it is unsafe for banking."]'::jsonb, '["Updates dey cover security loop-holes wey hackers don already know.", "Turn on automatic update for your phone and computer.", "If phone too old to receive update, e no safe for banking again."]'::jsonb, '{
    "situation": "Your smartphone prompts you to install a system update, but it requires restarting the phone during your busiest sales hour.", "warning_signs": ["Delaying critical updates repeatedly"], "risky_action": "Ignoring the update for months because you are busy.", "safe_action": "Scheduling the update to install automatically overnight while the phone is charging.", "explanation": "Cybercriminals automate attacks on devices running outdated software. Updating promptly closes the doors they rely on."
  }'::jsonb, '{
    "situation": "Your phone tell you say make you do system update, but e mean say you go restart the phone when customers dey plenty.", "warning_signs": ["Ignoring important updates steady"], "risky_action": "To ignore the update for months because you dey busy.", "safe_action": "To schedule the update make e install automatically for night when you dey sleep and phone dey charge.", "explanation": "Hackers dey use automated system attack phones wey use old software. If you update fast, you block the door wey dem dey use."
  }'::jsonb, E'Software updates do more than add new emojis; they patch critical security vulnerabilities. When a company releases an update to fix a bug, hackers immediately reverse-engineer the patch to figure out how to attack devices that haven\'t updated yet.\n\nMake updating a non-negotiable habit.', E'Software updates no be only to bring new emojis; dem dey patch very important security loopholes. When company release update to fix problem, hackers dey immediately study am to know how to attack phones wey never update.\n\nMake software update compulsory habit for your business.'),
  (10, 'Protect your business transactions when connecting to free internet at cafes, airports, and hotels.', 'Protect your business transaction when you connect to free internet for cafe, airport or hotel.', 5, null, '["Understand how public Wi-Fi can be intercepted", "Identify the risks of connecting to unknown networks", "Use VPNs to secure your connection"]'::jsonb, '["Understand how hackers dey tap public Wi-Fi", "Know the danger of connecting to any free network", "Learn how to use VPN to secure your internet"]'::jsonb, '["Avoid accessing bank accounts on free public Wi-Fi.", "Use your cellular data hotspot for sensitive business tasks.", "If you must use public Wi-Fi, use a trusted Virtual Private Network (VPN)."]'::jsonb, '["No ever open your bank account for free public Wi-Fi.", "Use your own phone hotspot if you want do sensitive business.", "If you must use public Wi-Fi, use original VPN."]'::jsonb, '{
    "situation": "You are traveling and need to pay a supplier urgently. You connect to a free network called ''Airport_Free_WiFi'' to open your banking app.", "warning_signs": ["Unsecured, open Wi-Fi network without a password", "Performing sensitive tasks on an untrusted network"], "risky_action": "Logging into your bank app to transfer the money over the open network.", "safe_action": "Turning off Wi-Fi and using your cellular data to make the transfer instead.", "explanation": "Hackers can easily set up fake Wi-Fi hotspots with names that look legitimate. Anything you type while connected can be intercepted."
  }'::jsonb, '{
    "situation": "You dey travel and you need to pay supplier urgently. You con connect to free network wey dem call ''Airport_Free_WiFi'' to open your bank app.", "warning_signs": ["Free Wi-Fi wey no get password", "Doing bank transfer for network wey you no trust"], "risky_action": "To log inside your bank app and do the transfer for the open network.", "safe_action": "To off your Wi-Fi and use your normal phone data do the transfer.", "explanation": "Hackers fit easily set up fake Wi-Fi hotspot give am name wey look real. Anything you type for there, dem fit tap am."
  }'::jsonb, E'Public Wi-Fi networks in coffee shops, airports, and hotels are convenient but inherently insecure. Because they are open, anyone on the same network can use inexpensive software to intercept the data passing between your device and the internet.\n\nTreat public Wi-Fi as a public conversation: do not share secrets while connected.', E'Public Wi-Fi for eatery, airport, and hotel dey sweet to use but e no secure at all. Because na free for all, anybody for the network fit use cheap software tap the data wey dey pass between your phone and internet.\n\nTreat public Wi-Fi like say you dey talk for market: no share your secret while you connect.'),
  (11, 'Learn how scammers impersonate your suppliers to redirect invoice payments to their own bank accounts.', 'Learn how scammers dey disguise as your supplier to change invoice payment to their own bank account.', 7, '/assets/smeshield/scenarios/logistics-receipt.jpg', '["Understand how Business Email Compromise (BEC) works", "Identify fake invoices and changed payment details", "Establish a secure payment verification policy"]'::jsonb, '["Understand how Business Email Compromise (BEC) dey work", "Know how to spot fake invoice and changed account number", "Create strong rule for how you dey confirm payment"]'::jsonb, '["Always verify any change in a supplier''s bank account details via a phone call.", "Do not reply to the email to confirm the change.", "Train your accounting staff to question sudden urgency from executives."]'::jsonb, '["Always use phone call confirm if your supplier change their bank account.", "No reply the same email to ask if na true.", "Train your accountant make dem dey question any urgent request from oga."]'::jsonb, '{
    "situation": "A supplier you work with regularly emails you a new invoice, but the email states they have recently changed their bank account details.", "warning_signs": ["Sudden change in payment details", "Pressure to pay the invoice immediately to avoid delays"], "risky_action": "Updating the bank account in your system and paying the invoice immediately.", "safe_action": "Calling the supplier on a known, trusted phone number to verify the account change before sending any money.", "explanation": "If the supplier''s email is hacked, the scammer can send authentic-looking emails from the real address, replacing only the bank details."
  }'::jsonb, '{
    "situation": "One supplier wey you dey do business with steady send you email with new invoice, but dem write say dem don change their bank account number.", "warning_signs": ["Sudden change of account number", "Pressure say make you pay the invoice immediately"], "risky_action": "To just change the account number for your record and pay the money immediately.", "safe_action": "To call the supplier for the normal phone number wey you know, to confirm the account change before you send money.", "explanation": "If hackers don take over the supplier email, dem fit send email wey look exactly like the real one, but na their own bank details dem go put."
  }'::jsonb, E'Business Email Compromise (BEC) is a sophisticated scam where criminals gain access to a business email account and impersonate the owner. They monitor conversations and wait for the perfect moment—like when a large invoice is due—to intercept the payment by supplying fraudulent bank details.\n\nA simple phone call can save your business millions.', E'Business Email Compromise (BEC) na very smart scam where criminals go gain access to business email account con disguise as the owner. Dem go monitor conversation con wait for the perfect time—like when big invoice don ready—to intercept the payment by supplying fake bank details.\n\nOne simple phone call fit save your business millions.'),
  (12, 'Avoid losing money to fake websites that look exactly like your trusted online suppliers.', 'Avoid losing money to fake websites wey look exactly like the online suppliers wey you trust.', 6, null, '["Identify typosquatting and fake URLs", "Recognize signs of fraudulent e-commerce sites", "Verify website authenticity before entering card details"]'::jsonb, '["Know how to spot fake website link and typosquatting", "Spot the signs of fake online shop", "Confirm if website na original before you put card details"]'::jsonb, '["Check the website URL carefully for misspellings (e.g., amaz0n.com).", "If prices are unbelievably low, it is likely a scam.", "Look for verifiable contact information and reviews off-site."]'::jsonb, '["Check the website link well-well for spelling mistake (e.g., amaz0n.com).", "If the price too cheap to be true, na scam.", "Check if dem get real contact address and read reviews outside the site."]'::jsonb, '{
    "situation": "You click a Facebook ad for wholesale inventory at 80% off. The website looks professional and has a secure padlock icon.", "warning_signs": ["Unrealistically low prices", "The URL contains extra words like ''official-discount-store''", "No physical address listed"], "risky_action": "Entering your debit card details to secure the amazing deal before it ends.", "safe_action": "Leaving the site and searching for the company name on Google to read independent reviews.", "explanation": "Scammers easily create beautiful, secure (HTTPS) websites that exist only to harvest your credit card information."
  }'::jsonb, '{
    "situation": "You click one Facebook ad for wholesale goods at 80% discount. The website look very standard and e even get padlock icon.", "warning_signs": ["The price too cheap to be true", "The website link get extra words like ''official-discount-store''", "Dem no put physical address"], "risky_action": "To put your debit card details make you fit grab the deal before e finish.", "safe_action": "To leave the site con search for the company name for Google to read wetin other people dey talk about dem.", "explanation": "Scammers fit easily build fine, secure (HTTPS) website wey dem just setup to steal your ATM card details."
  }'::jsonb, E'Fake online stores are designed to look identical to legitimate retailers. They lure you in with massive discounts on social media ads. However, once you pay, the goods never arrive, and your credit card details are sold on the dark web.\n\nThe presence of a padlock (HTTPS) only means the connection is encrypted; it does not mean the site itself is legitimate.', E'Fake online stores dey designed to look exactly like the real ones. Dem dey use massive discount for social media take draw people. But once you pay, you no go see any goods, and dem go sell your card details for dark web.\n\nThe padlock (HTTPS) wey you see for browser only mean say the connection secure; e no mean say the people behind the website no be scammers.'),
  (13, 'Recognize and stop scammers who use phone calls and AI voice cloning to impersonate bank officials or relatives.', 'Know how to stop scammers wey dey use phone call and AI voice trick pretend say dem be your bank manager or family member.', 6, null, '["Understand how voice phishing (vishing) works", "Recognize AI voice cloning tactics", "Implement safe verification for urgent phone requests"]'::jsonb, '["Understand how voice phishing dey work", "Know how scammers dey use AI copy voice", "Learn how to safely verify urgent request for phone call"]'::jsonb, '["Banks will never ask for your PIN or full card details over the phone.", "AI can clone a loved one''s voice using just a short audio clip from social media.", "Establish a ''safe word'' with your family for emergency money requests."]'::jsonb, '["Bank no go ever ask for your PIN or full card details for phone.", "AI fit copy your family member voice if dem get small audio from social media.", "Create ''safe word'' with your family for emergency money request."]'::jsonb, '{
    "situation": "You receive a frantic phone call from a number you do not recognize. The voice sounds exactly like your business partner, saying they have been arrested and urgently need bail money transferred to a specific account.", "warning_signs": ["Extreme urgency and panic", "Requesting money to an unknown account", "Calling from an unrecognized number"], "risky_action": "Transferring the money immediately out of fear for their safety.", "safe_action": "Hanging up and dialing your business partner''s known phone number to verify their safety.", "explanation": "AI voice cloning technology is now cheap and accessible. Scammers only need a 3-second clip of someone''s voice to make it say whatever they want."
  }'::jsonb, '{
    "situation": "You get one scatter-scatter phone call from number wey you no know. The voice sound exactly like your business partner, dey talk say police don hold am and e need bail money urgent to one account.", "warning_signs": ["Too much panic and urgency", "Asking for money to strange account", "Calling from number wey you no know"], "risky_action": "To transfer the money immediately because you dey fear for their life.", "safe_action": "To cut the call and dial your business partner real phone number to confirm if e dey safe.", "explanation": "AI voice technology don cheap now. Scammers only need 3-seconds audio of person voice to make am talk anything dem want."
  }'::jsonb, E'Voice phishing (Vishing) relies on creating panic over a phone call. Historically, scammers pretended to be bank managers. Today, they use AI to clone the voices of people you know and trust. \n\nAlways break the emotional chain. Hang up and call the person back on the number you already have saved in your contacts.', E'Voice phishing dey rely on making you panic for phone. Before before, scammers dey pretend say dem be bank manager. Today, dem dey use AI copy the voice of people wey you know and trust.\n\nAlways break the emotional chain. Cut the call and dial the person normal number wey you don save for your phone.'),
  (14, 'Learn why scanning random QR codes for payments or menus can lead to stolen credentials and drained accounts.', 'Learn why scanning any QR code for payment or menu fit make hackers steal your details and clear your account.', 5, null, '["Understand the security risks of QR codes", "Identify tampered or fake physical QR codes", "Safely inspect links before interacting"]'::jsonb, '["Understand the danger of QR codes", "Know how to spot fake or tampered QR codes for physical places", "Safely check links before you click am"]'::jsonb, '["A QR code is just a barcode that hides a website link.", "Scammers stick fake QR codes over real ones in parking lots and restaurants.", "Always check the URL preview on your phone screen before tapping to open it."]'::jsonb, '["QR code na just barcode wey dey hide website link.", "Scammers dey paste fake QR code on top original ones for public place.", "Always check the website link wey show for your phone screen before you click am."]'::jsonb, '{
    "situation": "You are at a restaurant and scan the QR code on the table to view the menu. It redirects you to a page asking you to log in with your Google account to view the PDF.", "warning_signs": ["Unnecessary login prompt just to view a menu", "The physical QR code looks like a sticker placed over another one"], "risky_action": "Entering your Google email and password so you can order food.", "safe_action": "Closing the page and asking the waiter for a physical menu or the direct website address.", "explanation": "Scammers place fake QR stickers in public places to route victims to phishing sites. A restaurant menu should never require your Google password."
  }'::jsonb, '{
    "situation": "You dey restaurant con scan the QR code for table to see their menu. E carry you go page wey say make you log in with your Google account before you fit see the PDF.", "warning_signs": ["Dem dey ask you to log in just to see menu", "The physical QR code look like sticker wey dem paste on top another one"], "risky_action": "To put your Google email and password so that you fit order food.", "safe_action": "To close the page and ask the waiter for physical menu or their direct website address.", "explanation": "Scammers dey paste fake QR sticker for public place to carry people go phishing site. Restaurant menu no suppose ever ask for your Google password."
  }'::jsonb, E'QR codes are incredibly convenient, but you cannot read them with your eyes. When you scan a QR code, your phone translates it into a link. Fraudsters exploit this by generating QR codes that link to malware downloads or fake payment portals, and pasting them over legitimate codes in public spaces.\n\nUse your phone\'s built-in scanner to preview the URL before visiting it, and never install apps prompted by a QR scan.', E'QR codes dey very convenient, but you no fit read am with your eyes. When you scan QR code, your phone go translate am to link. Scammers dey exploit this thing by creating QR codes wey dey link to virus or fake payment portal, con paste am on top real ones for public place.\n\nUse your phone camera preview the link before you open am, and no ever install app wey QR scan tell you to install.'),
  (15, 'Ensure your business survives even if your main phone or laptop is stolen, lost, or destroyed.', 'Make sure say your business fit survive even if your main phone or laptop lost, spoil, or dem steal am.', 6, '/assets/smeshield/scenarios/logistics-rider.jpg', '["Understand the impact of total data loss", "Implement automated cloud backups", "Enable remote wipe capabilities for business devices"]'::jsonb, '["Understand wetin fit happen if you lose all your data", "Learn how to do automatic cloud backup", "Turn on feature wey fit wipe your phone from far if e lost"]'::jsonb, '["If your phone is stolen today, your business should still be able to operate tomorrow.", "Set your important apps (like WhatsApp Business) to back up to the cloud daily.", "Use strong screen locks to prevent thieves from accessing your bank apps."]'::jsonb, '["If dem steal your phone today, your business suppose fit run tomorrow.", "Set your important apps (like WhatsApp Business) to backup to cloud everyday.", "Use strong screen lock so thieves no go fit open your bank apps."]'::jsonb, '{
    "situation": "Your business phone, containing all your customer contacts, pending orders, and un-backed-up WhatsApp chats, is stolen from your shop counter.", "warning_signs": ["Storing critical business data on only one physical device", "No cloud backups enabled"], "risky_action": "Trying to rebuild your contact list from memory while losing weeks of active orders.", "safe_action": "Logging into your cloud account from a new device to instantly restore all your contacts, chats, and files.", "explanation": "Hardware is replaceable; data is often not. A lost phone without a backup can bankrupt a small business overnight."
  }'::jsonb, '{
    "situation": "Dem steal your business phone for your shop counter. The phone carry all your customer contacts, pending orders, and WhatsApp chats wey you no backup.", "warning_signs": ["Keeping important business data inside only one physical phone", "You no set cloud backup"], "risky_action": "To dey try remember your contacts from head while you don lose weeks of active orders.", "safe_action": "To log inside your cloud account from new phone and immediately bring back all your contacts, chats, and files.", "explanation": "Money fit buy new phone; but money no fit buy lost data. Phone wey lost without backup fit crash small business overnight."
  }'::jsonb, E'Physical device theft is one of the most common threats to Nigerian businesses. The loss of a smartphone is not just the loss of the physical hardware—it is the loss of access to your bank, your customers, and your records.\n\nProtect your devices with strong biometrics or PINs, and ensure that automatic daily cloud backups are enabled for all critical business applications.', E'Phone and laptop theft na one of the most common threat to businesses for Nigeria. If you lose your smartphone, e no be just the physical phone you lose—you don lose access to your bank, your customers, and your market records.\n\nProtect your phones with strong PIN or fingerprint, and make sure say you turn on automatic daily cloud backup for all your important business apps.')
) as v(id, description_en, description_pcm, estimated_duration, image_url, learning_objectives_en, learning_objectives_pcm, key_takeaways_en, key_takeaways_pcm, scenario_en, scenario_pcm, content_en, content_pcm)
where m.order_index = v.id;